independent-practice.solution:
def reverse_words(sentence):
    words = sentence.split()
    words.reverse()
    return " ".join(words)

def column(rows, position):
    picked = []
    for row in rows:
        picked.append(row[position])
    return picked

def tidy_names(line):
    if line.strip() == "":
        return ""
    names = []
    for piece in line.split(","):
        names.append(piece.strip())
    names.sort()
    return ", ".join(names)

exam.solution:
def remove_all(items, value):
    kept = []
    for item in items:
        if item != value:
            kept.append(item)
    return kept

def longest_word(sentence):
    best = ""
    for word in sentence.split():
        if len(word) > len(best):
            best = word
    return best
